//! The Rust implementation of `artifact@1` against the committed contract.
//!
//! `server/contract/datastore/` holds the schemas, three example documents, and
//! 15 identity vectors generated by the Python reference implementation. This test
//! is the cross-check: the two implementations must produce the SAME hashes for
//! the same bytes, or one of them is wrong and every artifact identity is in
//! question.
//!
//! Without this, the contract is a document the Rust code merely resembles.

use std::path::PathBuf;

use munarium_datastore::model::{ArtifactBuildPlan, ArtifactManifest, BuildSpec};

fn contract_dir() -> PathBuf {
    // The crate lives at server/src/munarium-datastore; the contract is the
    // server tree's own, at server/contract/datastore, so nothing this
    // workspace tests reads outside server/.
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../contract/datastore")
        .canonicalize()
        .expect("the datastore contract directory should exist at server/contract/datastore")
}

fn read_json<T: serde::de::DeserializeOwned>(rel: &str) -> T {
    let path = contract_dir().join(rel);
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|e| panic!("parsing {} as the expected shape: {e}", path.display()))
}

fn vectors() -> serde_json::Value {
    read_json("vectors/identity-vectors.json")
}

fn vector(name: &str) -> serde_json::Value {
    vectors()["vectors"]
        .as_array()
        .expect("vectors is an array")
        .iter()
        .find(|v| v["name"] == name)
        .unwrap_or_else(|| panic!("no vector named {name}"))
        .clone()
}

/// Every committed example must deserialize into the Rust types. A field the
/// schema has and the struct lacks is silently dropped by serde, so this also
/// pins that the two shapes have not drifted apart.
#[test]
fn the_committed_examples_deserialize() {
    let _: BuildSpec = read_json("examples/build-spec.collection.json");
    let _: ArtifactBuildPlan = read_json("examples/artifact-plan.tantivy-exact.json");
    let _: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");
}

/// The cross-implementation check. If Rust and Python disagree here, an
/// artifact sealed by one cannot be verified by the other.
#[test]
fn rust_reproduces_the_python_identity_vectors() {
    let spec: BuildSpec = read_json("examples/build-spec.collection.json");
    let plan: ArtifactBuildPlan = read_json("examples/artifact-plan.tantivy-exact.json");
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");
    let base = vector("baseline");

    assert_eq!(
        spec.index_version_id().unwrap(),
        base["index_version_id"].as_str().unwrap(),
        "index_version_id disagrees with the Python reference"
    );
    assert_eq!(
        plan.plan_sha256().unwrap(),
        base["artifact_plan_sha256"].as_str().unwrap(),
        "artifact_plan_sha256 disagrees with the Python reference"
    );
    assert_eq!(
        manifest.artifact_id().unwrap(),
        base["artifact_id"].as_str().unwrap(),
        "artifact_id disagrees with the Python reference"
    );
}

/// The manifest's embedded hashes must be the hashes of the committed sidecars.
/// A stale value here would make every vector agree with itself and with
/// nothing real.
#[test]
fn the_manifest_embeds_the_real_sidecar_hashes() {
    let spec: BuildSpec = read_json("examples/build-spec.collection.json");
    let plan: ArtifactBuildPlan = read_json("examples/artifact-plan.tantivy-exact.json");
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");

    let spec_hash = munarium_datastore::canonical::canonical_sha256(&spec).unwrap();
    assert_eq!(manifest.build_spec_sha256, spec_hash);
    assert_eq!(manifest.artifact_plan_sha256, plan.plan_sha256().unwrap());
}

/// The invariant the whole logical/physical split exists for: an engine
/// revision change moves `artifact_id` and leaves `index_version_id` alone, so
/// an engine upgrade is a binding change rather than a reindex, and a session's
/// pin survives it.
#[test]
fn an_engine_revision_moves_only_the_artifact_id() {
    let spec: BuildSpec = read_json("examples/build-spec.collection.json");
    let plan: ArtifactBuildPlan = read_json("examples/artifact-plan.tantivy-exact.json");
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");

    let mut upgraded = plan.clone();
    upgraded.lexical.engine_revision = "0.23.0".to_string();

    let mut m = manifest.clone();
    m.artifact_plan_sha256 = upgraded.plan_sha256().unwrap();

    let expected = vector("lexical_engine_revision");
    assert_eq!(
        spec.index_version_id().unwrap(),
        expected["index_version_id"].as_str().unwrap(),
        "the LOGICAL id must not move when only the engine changed"
    );
    assert_eq!(
        m.artifact_id().unwrap(),
        expected["artifact_id"].as_str().unwrap(),
        "the artifact id must move, and must match the Python reference"
    );
    assert_ne!(m.artifact_id().unwrap(), manifest.artifact_id().unwrap());
}

/// The other half of the V1 decision: the analyzer contract IS a logical input,
/// so a tokenizer change produces a new logical version that must be activated
/// like any corpus change.
#[test]
fn a_tokenizer_change_moves_the_logical_id() {
    let spec: BuildSpec = read_json("examples/build-spec.collection.json");
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");

    let mut changed = spec.clone();
    changed.lexical_analysis.tokenizer = "munarium-pg-compat@2".to_string();

    let mut m = manifest.clone();
    m.build_spec_sha256 = munarium_datastore::canonical::canonical_sha256(&changed).unwrap();

    let expected = vector("analyzer_tokenizer");
    assert_eq!(
        changed.index_version_id().unwrap(),
        expected["index_version_id"].as_str().unwrap()
    );
    assert_eq!(
        m.artifact_id().unwrap(),
        expected["artifact_id"].as_str().unwrap()
    );
    assert_ne!(
        changed.index_version_id().unwrap(),
        spec.index_version_id().unwrap()
    );
}

/// Source order is content: two builds of the same SET that disagree by
/// permutation are not the same build, because the builder streams in this
/// order.
#[test]
fn reordering_sources_moves_the_logical_id() {
    let spec: BuildSpec = read_json("examples/build-spec.collection.json");
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");

    let mut reversed = spec.clone();
    reversed.sources.reverse();

    let mut m = manifest.clone();
    m.build_spec_sha256 = munarium_datastore::canonical::canonical_sha256(&reversed).unwrap();

    let expected = vector("source_order");
    assert_eq!(
        reversed.index_version_id().unwrap(),
        expected["index_version_id"].as_str().unwrap()
    );
    assert_eq!(
        m.artifact_id().unwrap(),
        expected["artifact_id"].as_str().unwrap()
    );
}

/// A lexical-only corpus is valid and is NOT the same logical corpus as a
/// hybrid one -- so dropping the embedder is a logical change, not a physical
/// one.
#[test]
fn removing_the_embedder_moves_the_logical_id() {
    let spec: BuildSpec = read_json("examples/build-spec.collection.json");
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");

    let mut lexical_only = spec.clone();
    lexical_only.embedder = None;

    let mut m = manifest.clone();
    m.build_spec_sha256 = munarium_datastore::canonical::canonical_sha256(&lexical_only).unwrap();

    let expected = vector("embedder_absent");
    assert_eq!(
        lexical_only.index_version_id().unwrap(),
        expected["index_version_id"].as_str().unwrap()
    );
    assert_eq!(
        m.artifact_id().unwrap(),
        expected["artifact_id"].as_str().unwrap()
    );
}

/// Reordering an ARRAY is a different manifest, because canonicalization sorts
/// object members and never array elements. The contract records this as an
/// `artifact`-class move, and the Rust side must agree.
#[test]
fn reordering_probes_moves_the_artifact_id() {
    let manifest: ArtifactManifest = read_json("examples/manifest.tantivy-exact.json");
    let mut m = manifest.clone();
    m.probes.reverse();

    let expected = vector("probe_order_is_content");
    assert_eq!(
        m.artifact_id().unwrap(),
        expected["artifact_id"].as_str().unwrap()
    );
    assert_ne!(m.artifact_id().unwrap(), manifest.artifact_id().unwrap());
}
